);
// ── 2. Reset ──────────────────────────────────────────────────────────────
Clear(colTimelineRows_R01); Clear(colTimelineRows_R02); Clear(colTimelineRows_R03);
Clear(colTimelineRows_R04); Clear(colTimelineRows_R05); Clear(colTimelineRows_R06);
// ── 3. Build timeline rows ────────────────────────────────────────────────
// _s/_e = window start/end aliases — avoids repeating the var names in every free-slot record.
// Each room block:
//   (a) collect all booked rows in one call
//   (b) insert leading free slot if day doesn't open with a booking
//   (c) insert gap / trailing free slots after each booking
//   (d) sort by RowStart
With({_s: varFindWindowStart, _e: varFindWindowEnd},
    // ── R01 ───────────────────────────────────────────────────────────────
    With({room: Filter(varFindBookings, RoomID.Id = 1)},
        Collect(colTimelineRows_R01,                                                     // (a)
            ForAll(room As b, {
                RowType:   "booked",
                RowStart:  b.StartDateTime,
                RowEnd:    b.EndDateTime,
                RowHeight: DateDiff(b.StartDateTime, b.EndDateTime, TimeUnit.Minutes) / 60 * 120,
                Title:     b.Title,
                BookedBy:  b.BookedBy.DisplayName
            })
        );
        If(IsEmpty(room),                                                                // (b)
            Collect(colTimelineRows_R01, {RowType:"free",RowStart:_s,RowEnd:_e,
                RowHeight:DateDiff(_s,_e,TimeUnit.Minutes)/60*120,Title:"",BookedBy:""}),
            First(room).StartDateTime > _s,
            Collect(colTimelineRows_R01, {RowType:"free",RowStart:_s,RowEnd:First(room).StartDateTime,
                RowHeight:DateDiff(_s,First(room).StartDateTime,TimeUnit.Minutes)/60*120,Title:"",BookedBy:""})
        );
        ForAll(room As b,                                                                // (c)
            With({next: LookUp(room, StartDateTime > b.EndDateTime, StartDateTime)},
                If(IsBlank(next) && b.EndDateTime < _e,
                    Collect(colTimelineRows_R01, {RowType:"free",RowStart:b.EndDateTime,RowEnd:_e,
                        RowHeight:DateDiff(b.EndDateTime,_e,TimeUnit.Minutes)/60*120,Title:"",BookedBy:""}),
