                    Collect(colTimelineRows_R01, {RowType:"free",RowStart:b.EndDateTime,RowEnd:next,
                        RowHeight:DateDiff(b.EndDateTime,next,TimeUnit.Minutes)/60*120,Title:"",BookedBy:""})
                )
            )
        );
        ClearCollect(colTimelineRows_R01, Sort(colTimelineRows_R01, RowStart, SortOrder.Ascending)) // (d)
    );
